\label{df:pairwise_Lip}
A graph signal $\mathbf{x}$ with unit norm is~\emph{pairwise Lipschitz smooth} with parameter $C$ when it satisfies
\begin{equation*}
	| x_i - x_j |   \ \leq \  C \ d(v_i, v_j),~{\rm for~all~} i,j = 0, 1, \ldots, N-1,
\end{equation*}
with $d(v_i, v_j)$ the distance between the $i$th and the $j$th nodes.

\begin{equation*}
	| x_i - x_j |   \ \leq \  C \ d(v_i, v_j),~{\rm for~all~} i,j = 0, 1, \ldots, N-1,
\end{equation*}

\label{df:polynomial_sig}
A graph signal $\mathbf{x}$ is polynomial with degree $K$ when
\begin{equation*}
	\mathbf{x} \ = \  \mathrm{D}_{\rm poly(K)}  \mathbf{a} \ = \ \begin{bmatrix}
	{\bf 1}  &  \mathrm{D}^{(1)}  & \mathrm{D}^{(2)}  &  \ldots &  \mathrm{D}^{(K)} 
	\end{bmatrix} 
	\mathbf{a} \in \ensuremath{\mathbb{R}}^N,
\end{equation*}
where $\mathbf{a} \in \ensuremath{\mathbb{R}}^{KN+1}$ and $\mathrm{D}_{\rm poly(K)} $ is a graph polynomial dictionary with $\mathrm{D}^{(k)}_{i,j} = d^k(v_i, v_j)$. Denote this class by $\mathrm{PL}(K)$.

 ({\bf Graph polynomial dictionary represents the pairwise Lipschiz smooth signals})
\label{thm:BLvsGS}
$\mathrm{PL}(1)$ is a subset of the pairwise Lipschitz smooth with some parameter $C$.

A graph signal $\mathbf{x}$ is bandlimited with respect to a graph Fourier basis $\mathrm{V}$ with bandwidth $K$ when
\begin{equation*}
	\mathbf{x} = \mathrm{V}_{(K)} \mathbf{a},
\end{equation*}
where $\mathbf{a} \in \ensuremath{\mathbb{R}}^{K}$ and $\mathrm{V}_{(K)}$ is a submatrix containing the first $K$ columns of $\mathrm{V}$. Denote this class by $\mathrm{BL}_{\mathrm{V}}(K)$~\cite{ChenVSK:15}.

 ({\bf The graph Fourier basis of the graph Laplacian represents the total Lipschiz smooth signals})
\label{thm:BLvsGS}
For any $K \in \{1, \cdots, N \}$, $\mathrm{BL}_{\mathrm{V}_{\mathrm{L}}}(K)$ is a subset of the total Lipschitz smooth with parameter $C$, when $C \geq \lambda^{(\mathrm{L})}_k$.

({\bf The graph Fourier basis of the transition matrix represents the local normalized neighboring smooth signals})
\label{thm:LNNS}
For any $K \in \{1, \cdots, N \}$, $\mathrm{BL}_{\mathrm{V}_{\mathrm{P}}}(K)$ is a subset of the local normalized neighboring smooth with parameter $C$, when $C \geq  (1 - \lambda^{(\mathrm{P})}_{K})^2$.

 ({\bf The graph Fourier basis of the adjacency matrix represents the global normalized neighboring smooth signals})
\label{thm:GNNS}
For any $K \in \{1, \cdots, N \}$, $\mathrm{BL}_{\mathrm{V}_{\mathrm{W}}}(K)$ is a subset of the global normalized neighboring smooth with parameter $C$, when $C \geq  (1 - \lambda^{(\mathrm{W})}_{K} / |\lambda_{\max}{(\mathrm{W})}| )^2$.

\label{df:concentrate_v}
A graph signal $\mathbf{x}$ is~\emph{$\epsilon$-vertex concentrated} on a graph vertex set $\Gamma$ when it satisfies
\begin{equation*}
	\left\| \mathbf{x} - \mathrm{I}_{\Gamma} \mathbf{x} \right\|_2^2 \leq \epsilon,
\end{equation*}
where $\mathrm{I}_{\Gamma} \in \ensuremath{\mathbb{R}}^{N \times N}$ is a diagonal matrix, with $(\mathrm{I}_{\Gamma})_{i,i} = 1$ when $i \in \Gamma$ and $0$, otherwise.

\label{df:concentrate_s}
A graph signal $\mathbf{x}$ is~\emph{$\epsilon$-spectrum concentrated} on a graph spectrum band $\Omega$ when it satisfies
\begin{equation*}
	\left\| \mathbf{x} - \mathrm{V}_{\Omega} \mathrm{U}_{\Omega} \mathbf{x} \right\|_2^2 \leq \epsilon,
\end{equation*}
where $ \mathrm{V}_{\Omega} \in \ensuremath{\mathbb{R}}^{N \times |\Omega|}$ is a submatrix of $\mathrm{V}$ with columns selected by $\Omega$ and $ \mathrm{U}_{\Omega} \in \ensuremath{\mathbb{R}}^{|\Omega| \times N}$ is a submatrix of $\mathrm{V}$ with rows selected by $\Omega$.

({\bf Uncertainty principle of the graph vertex and spectrum domains})
\label{thm:GNNS}
Let a unit norm signal $\mathbf{x}$ supported on an undirected graph  be $\epsilon_{\Gamma}$-vertex concentrated and $\epsilon_{\Omega}$-spectrum concentrated at the same time. Then,
\begin{equation*}
|\Gamma| \cdot |\Omega| \geq  \frac{(1 - (\epsilon_{\Omega}  +  \epsilon_{\Gamma} ))^2 }{ \left\| \mathrm{U}_{\Omega} \right\|_{\infty}^2 }.
\end{equation*}

 We first show $\left\| \mathrm{V}_{\Omega} \mathrm{U}_{\Omega}  \mathrm{I}_{\Gamma} \right\|_2 \leq \left\| \mathrm{U}_{\Omega} \right\|_{\infty}  \sqrt{ |\Gamma|\cdot |\Omega|}$.
\begin{eqnarray*}
&&	( \mathrm{V}_{\Omega} \mathrm{U}_{\Omega} \mathrm{I}_{\Gamma}  \mathbf{x} )_s
\ = \ \sum_{k \in \Omega} \mathrm{V}_{s,k} \left( \sum_{i \in \Gamma} \mathrm{U}_{k,i} x_i \right)
\\
& = &  \sum_{i \in \Gamma}  \left(   \sum_{k \in \Omega} \mathrm{V}_{s,k} \mathrm{U}_{k,i} \right) x_i
\ = \ \sum_i q(s,i) x_i,
\end{eqnarray*}
   where
   \begin{equation*}
	\label{eq:Delta}
	q(s,i) = 
  \left\{ 
    \begin{array}{rl}
      \sum_{k \in \Omega} \mathrm{V}_{s,k} \mathrm{U}_{k,i}, & i \in \Gamma;\\
      0, & \mbox{otherwise}.
  \end{array} \right.
\end{equation*}
Let $\mathbf{y}^{(i)}$ be a graph signal with $y^{(i)}_s = q(s,i)$. Then, $( \widehat{\mathbf{y}^{(i)}} )_k = {\bf 1}_{k \in \Omega} \mathrm{U}_{k,i}$. We then have
\begin{eqnarray*}
&&	\left\| \mathrm{V}_{\Omega} \mathrm{U}_{\Omega} \mathrm{I}_{\Gamma}  \right\|_{2}^2
 \ \leq \  \left\| \mathrm{V}_{\Omega} \mathrm{U}_{\Omega} \mathrm{I}_{\Gamma}  \right\|_{\rm HS}^2
\\
& = & \sum_{i \in \Gamma} \sum_{s} |q(s,i)|^2 
\ =  \sum_{i \in \Gamma} \left\| \mathbf{y}^{(i)} \right\|_2^2
\\
& = & \sum_{i \in \Gamma} \left\| \widehat{ \mathbf{y}^{(i)} } \right\|_2^2
\ = \  \sum_{i \in \Gamma} \sum_{k} \left( {\bf 1}_{k \in \Omega} \mathrm{U}_{k,i} \right)^2
\\
& \leq & \left\| \mathrm{U}_{\Omega} \right\|_{\infty}^2 \sum_{i \in \Gamma} \sum_{k} {\bf 1}_{k \in \Omega} 
\ = \   \left\| \mathrm{U}_{\Omega} \right\|_{\infty}^2 |\Gamma| \cdot |\Omega|.
\end{eqnarray*}

We then show that $\left\|  \mathrm{V}_{\Omega} \mathrm{U}_{\Omega} \mathrm{I}_{\Gamma} \mathbf{x}  \right\|_2 \geq 1 - (\epsilon_{\Omega}  +  \epsilon_{\Gamma} )$.
Based on the assumption, we have
   \begin{eqnarray*}
 &&  \left\| \mathbf{x} - \mathrm{V}_{\Omega} \mathrm{U}_{\Omega} \mathrm{I}_{\Gamma}  \mathbf{x}  \right\|_2
   \\
& = &   \left\| \mathbf{x} - \mathrm{I}_{\Gamma} \mathbf{x} \right\|_2  + \left\| \mathrm{I}_{\Gamma} \mathbf{x} -  \mathrm{V}_{\Omega} \mathrm{U}_{\Omega} \mathrm{I}_{\Gamma} \mathbf{x}  \right\|_2 
	\\
& \leq & \epsilon_{\Omega}  +  \epsilon_{\Gamma}. 
   \end{eqnarray*}
Since $\mathbf{x}$ has a unit norm, by the triangle inequality,  we have
   \begin{equation*}
  \left\|  \mathrm{V}_{\Omega} \mathrm{U}_{\Omega} \mathrm{I}_{\Gamma}  \right\|_2 \geq 1 - (\epsilon_{\Omega}  +  \epsilon_{\Gamma} ).
   \end{equation*}
Finally, we combine two results and obtain  
\begin{equation*}
|\Gamma|\cdot |\Omega|  \geq  \frac{\left\| \mathrm{V}_{\Omega} \mathrm{U}_{\Omega}  \mathrm{I}_{\Gamma} \right\|_2^2}{\left\| \mathrm{U}_{\Omega} \right\|_{\infty}^2 } \ > \ \frac{  (1 - (\epsilon_{\Omega}  +  \epsilon_{\Gamma} ))^2 }{ \left\| \mathrm{U}_{\Omega} \right\|_{\infty}^2}
\end{equation*}

